type Decision = Either[String, Unit]
type Policy[R] = (SecurityContext, Action, R) => Decision

def guard[R, T](policy: Policy[R], ctx: SecurityContext, a: Action, r: R)
               (op: => T): T =
  policy(ctx, a, r) match {
    case Left(reason) => throw AccessDenied(reason)   // deny by default
    case Right(_)     => op                           // rule-free resource code
  }

